    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ001Enabled', 'DQ-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ002Enabled', 'DQ-002');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ004Enabled', 'DQ-004');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ005Enabled', 'DQ-005');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ006Enabled', 'DQ-006');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ007Enabled', 'DQ-007');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ008Enabled', 'DQ-008');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeDQ009Enabled', 'DQ-009');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeSS001Enabled', 'SS-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeSS002Enabled', 'SS-002');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeSS003Enabled', 'SS-003');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeSS004Enabled', 'SS-004');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeCV001Enabled', 'CV-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeCV002Enabled', 'CV-002');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeCV003Enabled', 'CV-003');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeCV004Enabled', 'CV-004');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodePR001Enabled', 'PR-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodePR002Enabled', 'PR-002');
