    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeBR001Enabled', 'BR-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeBR002Enabled', 'BR-002');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodeBR003Enabled', 'BR-003');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodePB001Enabled', 'PB-001');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodePB002Enabled', 'PB-002');
    ABSInventParametersEventHandler::loadCheckCodeToggle(sender, 'ABSCheckCodePB003Enabled', 'PB-003');
