private static void loadCheckCodeToggle(xFormRun _formRun, str _controlName, ABSMRPCheckCode _checkCode)
{
    FormCheckBoxControl checkBoxControl = _formRun.design().controlName(_controlName) as FormCheckBoxControl;

    if (checkBoxControl)
    {
        checkBoxControl.value(ABSMRPAssessmentCheckConfig::getEnabled(_checkCode));
    }
}

private static void saveCheckCodeToggle(FormControl _sender, ABSMRPCheckCode _checkCode)
{
    FormCheckBoxControl checkBoxControl = _sender as FormCheckBoxControl;

    if (checkBoxControl)
    {
        ABSMRPAssessmentCheckConfig::setEnabled(_checkCode, checkBoxControl.value() ? NoYes::Yes : NoYes::No);
    }
}

